package org.jsoup.safety;

import java.io.*;
import java.math.*;
import java.util.*;
import org.jsoup.Document;
import org.jsoup.helper.Validate;
import org.jsoup.nodes.Attribute;
import org.jsoup.nodes.Attributes;
import org.jsoup.nodes.DataNode;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.DocumentType;
import org.jsoup.nodes.Element;
import org.jsoup.nodes.Node;
import org.jsoup.nodes.TextNode;
import org.jsoup.parser.ParseErrorList;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.safety.Cleaner;
import org.jsoup.select.Elements;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Test;
import static org.jsoup.safety.CleanerTestUtil.createCleanDocument;
import static org.jsoup.safety.CleanerTestUtil.createDirtyDocument;
import static org.junit.Assert.*;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class Cleaner_isValid_TriageGen1Test {

    @Test
    public void testValidDocument() {
        // Given
        Document dirtyDocument = createDirtyDocument();
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertTrue(isValid);
    }

    @Test
    public void testInvalidDocument() {
        // Given
        Document dirtyDocument = createDirtyDocument();
        dirtyDocument.body().appendChild(new Element("script"));
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertFalse(isValid);
    }

    @Test
    public void testNullDocument() {
        // Given
        Document dirtyDocument = null;
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertFalse(isValid);
    }

    @Test
    public void testDocumentWithEmptyBody() {
        // Given
        Document dirtyDocument = createDirtyDocument();
        dirtyDocument.body().appendChild(new DocumentType("html"));
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertFalse(isValid);
    }

    @Test
    public void testDocumentWithScriptTag() {
        // Given
        Document dirtyDocument = createDirtyDocument();
        dirtyDocument.body().appendChild(new Element("script"));
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertFalse(isValid);
    }

    @Test
    public void testDocumentWithImgTag() {
        // Given
        Document dirtyDocument = createDirtyDocument();
        dirtyDocument.body().appendChild(new Element("img"));
        Cleaner cleaner = new Cleaner(createWhitelist());

        // When
        boolean isValid = cleaner.isValid(dirtyDocument);

        // Then
        assertTrue(isValid);
    }

    private Whitelist createWhitelist() {
        // Create a whitelist with allowed tags
        Whitelist whitelist = new Whitelist();
        whitelist.addTags("p", "img", "span");
        return whitelist;
    }

    private static Document createDirtyDocument() {
        Document dirtyDocument = Document.createShell("https://example.com");
        dirtyDocument.body().appendChild(new Element("p"));
        return dirtyDocument;
    }

    private static Document createCleanDocument() {
        Document cleanDocument = Document.createShell("https://example.com");
        cleanDocument.body().appendChild(new Element("p"));
        return cleanDocument;
    }
}
